{
  "root": "root_stack",
  "state": {
    "cameras": [
      {
        "id": "fuji",
        "option": "Option 1",
        "name": "Fujifilm X-S20",
        "description": "Best for color science and battery life",
        "feature": "7-stop IBIS",
        "url": "https://fujifilm-x.com/global/products/cameras/x-s20/",
        "buttonLabel": "View X-S20 Specs",
        "imageUrl": "https://storage.googleapis.com/gen-ui-asssets/r_000175_01_3_fujifilm_camera.jpg"
      },
      {
        "id": "sony",
        "option": "Option 2",
        "name": "Sony a6700",
        "description": "Best for autofocus and lens selection",
        "feature": "AI-driven Subject Tracking",
        "url": "https://electronics.sony.com/imaging/interchangeable-lens-cameras/aps-c/p/ilce6700-b",
        "buttonLabel": "View a6700 Details",
        "imageUrl": "https://storage.googleapis.com/gen-ui-asssets/r_000175_01_4_sony_alpha_camera.jpg"
      },
      {
        "id": "om",
        "option": "Option 3",
        "name": "OM System OM-5",
        "description": "Best for durability and compactness",
        "feature": "IP53 Weather Sealing",
        "url": "https://explore.omsystem.com/us/en/om-5",
        "buttonLabel": "View OM-5 Features",
        "imageUrl": "https://storage.googleapis.com/gen-ui-asssets/r_000175_01_5_nature_photography_camera.jpg"
      }
    ]
  },
  "elements": {
    "root_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "lg",
        "padding": 16
      },
      "children": [
        "title",
        "intro_text",
        "criteria_title",
        "criteria_intro",
        "criteria_list",
        "recommendations_title",
        "camera_card_template",
        "specs_title",
        "specs_table",
        "quick_actions_title",
        "quick_actions_stack",
        "sources_title",
        "sources_stack"
      ]
    },
    "title": {
      "type": "Text",
      "props": {
        "text": "Top Travel Mirrorless Recommendations",
        "variant": "h1"
      },
      "children": []
    },
    "intro_text": {
      "type": "Text",
      "props": {
        "text": "For a travel photographer needing portability without sacrificing stability, the best options released between 2020 and 2023 are the Fujifilm X-S20, Sony a6700, and OM System OM-5. These models specifically address your need for In-Body Image Stabilization (IBIS) in a chassis under 500g, while offering distinct advantages in lens ecosystems and color science.",
        "variant": "body"
      },
      "children": []
    },
    "criteria_title": {
      "type": "Text",
      "props": {
        "text": "Criteria and Pricing Context",
        "variant": "h2"
      },
      "children": []
    },
    "criteria_intro": {
      "type": "Text",
      "props": {
        "text": "The recommendations below adhere strictly to your budget cap of $1,500 USD and weight limit of 500g (body including battery). Prices listed are approximate body-only retail prices as of late 2023/early 2024.",
        "variant": "body"
      },
      "children": []
    },
    "criteria_list": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md"
      },
      "children": [
        "criteria_item_1",
        "criteria_item_2",
        "criteria_item_3"
      ]
    },
    "criteria_item_1": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "md",
        "align": "center"
      },
      "children": [
        "criteria_icon_1",
        "criteria_text_1"
      ]
    },
    "criteria_icon_1": {
      "type": "Icon",
      "props": {
        "name": "https://storage.googleapis.com/gen-ui-asssets/r_000175_01_6_feather.svg"
      },
      "children": []
    },
    "criteria_text_1": {
      "type": "Text",
      "props": {
        "text": "**Weight:** Includes battery and memory card to reflect real-world travel load.",
        "variant": "body"
      },
      "children": []
    },
    "criteria_item_2": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "md",
        "align": "center"
      },
      "children": [
        "criteria_icon_2",
        "criteria_text_2"
      ]
    },
    "criteria_icon_2": {
      "type": "Icon",
      "props": {
        "name": "https://storage.googleapis.com/gen-ui-asssets/r_000175_01_1_camera.svg"
      },
      "children": []
    },
    "criteria_text_2": {
      "type": "Text",
      "props": {
        "text": "**Lens Ecosystem:** \"Affordable\" is defined by the availability of third-party options (Sigma, Tamron) or a mature Micro Four Thirds market.",
        "variant": "body"
      },
      "children": []
    },
    "criteria_item_3": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "md",
        "align": "center"
      },
      "children": [
        "criteria_icon_3",
        "criteria_text_3"
      ]
    },
    "criteria_icon_3": {
      "type": "Icon",
      "props": {
        "name": "https://storage.googleapis.com/gen-ui-asssets/r_000175_01_7_activity.svg"
      },
      "children": []
    },
    "criteria_text_3": {
      "type": "Text",
      "props": {
        "text": "**IBIS:** All selected models feature 5-axis in-body stabilization, essential for handheld travel shots in low light or video.",
        "variant": "body"
      },
      "children": []
    },
    "recommendations_title": {
      "type": "Text",
      "props": {
        "text": "Recommended Models",
        "variant": "h2"
      },
      "children": []
    },
    "camera_card_template": {
      "type": "Card",
      "props": {},
      "children": [
        "camera_card_stack"
      ],
      "repeat": {
        "statePath": "/cameras",
        "key": "id"
      }
    },
    "camera_card_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md"
      },
      "children": [
        "camera_image",
        "camera_text_stack"
      ]
    },
    "camera_image": {
      "type": "Image",
      "props": {
        "url": {
          "$item": "imageUrl"
        },
        "fit": "cover",
        "height": 200
      },
      "children": []
    },
    "camera_text_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm",
        "padding": 16
      },
      "children": [
        "camera_title",
        "camera_description",
        "camera_feature",
        "camera_button"
      ]
    },
    "camera_title": {
      "type": "Text",
      "props": {
        "text": {
          "$template": "${option}: ${name}"
        },
        "variant": "h3"
      },
      "children": []
    },
    "camera_description": {
      "type": "Text",
      "props": {
        "text": {
          "$item": "description"
        },
        "variant": "body"
      },
      "children": []
    },
    "camera_feature": {
      "type": "Text",
      "props": {
        "text": {
          "$item": "feature"
        },
        "variant": "caption"
      },
      "children": []
    },
    "camera_button": {
      "type": "Button",
      "props": {
        "label": {
          "$item": "buttonLabel"
        },
        "variant": "primary"
      },
      "children": [],
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": {
              "$item": "url"
            }
          }
        }
      }
    },
    "specs_title": {
      "type": "Text",
      "props": {
        "text": "Technical Specifications Table",
        "variant": "h2"
      },
      "children": []
    },
    "specs_table": {
      "type": "Table",
      "props": {
        "columns": [
          {
            "key": "feature",
            "label": "Feature"
          },
          {
            "key": "fujifilm",
            "label": "Fujifilm X-S20"
          },
          {
            "key": "sony",
            "label": "Sony a6700"
          },
          {
            "key": "om_system",
            "label": "OM System OM-5"
          }
        ],
        "rows": [
          {
            "feature": "Release Year",
            "fujifilm": "May 2023",
            "sony": "July 2023",
            "om_system": "Oct 2022"
          },
          {
            "feature": "Sensor Size",
            "fujifilm": "APS-C (26MP)",
            "sony": "APS-C (26MP)",
            "om_system": "Micro 4/3 (20MP)"
          },
          {
            "feature": "Weight (Body)",
            "fujifilm": "~491g",
            "sony": "~493g",
            "om_system": "~414g"
          },
          {
            "feature": "Est. Price",
            "fujifilm": "~$1,299",
            "sony": "~$1,398",
            "om_system": "~$1,199"
          },
          {
            "feature": "Lens Mount",
            "fujifilm": "Fuji X Mount",
            "sony": "Sony E-Mount",
            "om_system": "Micro Four Thirds"
          },
          {
            "feature": "IBIS Rating",
            "fujifilm": "Up to 7.0 stops",
            "sony": "Up to 5.0 stops",
            "om_system": "Up to 7.5 stops"
          }
        ],
        "domain": "generic",
        "preferredPresentation": "table",
        "sourceFormat": "markdown",
        "sourceText": "| Feature | Fujifilm X-S20 | Sony a6700 | OM System OM-5 |\n| :--- | :--- | :--- | :--- |\n| Release Year | May 2023 | July 2023 | Oct 2022 |\n| Sensor Size | APS-C (26MP) | APS-C (26MP) | Micro 4/3 (20MP) |\n| Weight (Body) | ~491g | ~493g | ~414g |\n| Est. Price | ~$1,299 | ~$1,398 | ~$1,199 |\n| Lens Mount | Fuji X Mount | Sony E-Mount | Micro Four Thirds |\n| IBIS Rating | Up to 7.0 stops | Up to 5.0 stops | Up to 7.5 stops |"
      },
      "children": []
    },
    "quick_actions_title": {
      "type": "Text",
      "props": {
        "text": "Quick Actions",
        "variant": "h2"
      },
      "children": []
    },
    "quick_actions_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "md",
        "wrap": "wrap"
      },
      "children": [
        "action_button_1",
        "action_button_2"
      ]
    },
    "action_button_1": {
      "type": "Button",
      "props": {
        "label": "Compare Sensor Sizes"
      },
      "children": [],
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.dpreview.com/articles/8670169226/sensor-sizes-explained"
          }
        }
      }
    },
    "action_button_2": {
      "type": "Button",
      "props": {
        "label": "Search Used Lenses"
      },
      "children": [],
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.mpb.com/en-us"
          }
        }
      }
    },
    "sources_title": {
      "type": "Text",
      "props": {
        "text": "Sources",
        "variant": "h2"
      },
      "children": []
    },
    "sources_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "source_1",
        "source_2",
        "source_3"
      ]
    },
    "source_1": {
      "type": "Button",
      "props": {
        "label": "1. Fujifilm X-S20 Official Specifications",
        "variant": "borderless"
      },
      "children": [],
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://fujifilm-x.com/global/products/cameras/x-s20/specifications/"
          }
        }
      }
    },
    "source_2": {
      "type": "Button",
      "props": {
        "label": "2. Sony a6700 Product Page",
        "variant": "borderless"
      },
      "children": [],
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://electronics.sony.com/imaging/interchangeable-lens-cameras/aps-c/p/ilce6700-b"
          }
        }
      }
    },
    "source_3": {
      "type": "Button",
      "props": {
        "label": "3. OM System OM-5 Overview",
        "variant": "borderless"
      },
      "children": [],
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://explore.omsystem.com/us/en/om-5"
          }
        }
      }
    }
  }
}
